// REST approach - client must know the endpoint and contract
[ApiController]
[Route("api/[controller]")]
public class ProductsController : ControllerBase
{
    private readonly IProductRepository _repository;

    public ProductsController(IProductRepository repository)
    {
        _repository = repository;
    }

    [HttpGet("search")]
    public async Task<ActionResult<IEnumerable<Product>>> Search(
        [FromQuery] string query,
        [FromQuery] string? category,
        [FromQuery] int page = 1,
        CancellationToken cancellationToken = default)
    {
        var results = await _repository.SearchAsync(query, category, page, cancellationToken);
        return Ok(results);
    }
}
// Client usage:
//   GET /api/products/search?query=wireless+headphones&category=electronics&page=1
// Expected: 200 OK with JSON array of products

// MCP approach - client discovers the tool and its schema dynamically
public class SearchProductsTool
{
    private readonly IProductRepository _repository;

    public SearchProductsTool(IProductRepository repository)
    {
        _repository = repository;
    }

    public string Name => "search_products";
    public string Description => "Search products by keyword or category.";

    public object InputSchema => new
    {
        type = "object",
        properties = new
        {
            query = new { type = "string", description = "Search keyword" },
            category = new { type = "string", description = "Optional category filter" },
            page = new { type = "integer", description = "Page number (1-based)" }
        },
        required = new[] { "query" }
    };

    public async Task<string> ExecuteAsync(
        IReadOnlyDictionary<string, object?> args,
        CancellationToken cancellationToken)
    {
        try
        {
            var query = args.GetValueOrDefault("query")?.ToString() ?? string.Empty;
            var category = args.GetValueOrDefault("category")?.ToString();
            var page = args.GetValueOrDefault("page") is int p ? p : 1;
            var results = await _repository.SearchAsync(query, category, page, cancellationToken);
            return JsonSerializer.Serialize(results);
        }
        catch (OperationCanceledException)
        {
            return "Request was cancelled.";
        }
        catch (Exception ex)
        {
            return $"Error: {ex.Message}";
        }
    }
}
// Client discovers the tool via MCP handshake, then invokes:
//   tool: search_products
//   arguments: { query: "wireless headphones", category: "electronics", page: 1 }
// Expected: JSON result without the client hardcoding endpoint URLs
